mapper.select:
SELECT o.order_no as id, cust.nickname as customerName, p.name as productName, p.gpu_count as productQuantity, DATE_FORMAT(o.start_time, '%Y-%m-%d') as startTime, CASE WHEN o.end_time IS NULL THEN '无固定期限' ELSE DATE_FORMAT(o.end_time, '%Y-%m-%d') END as endTime, o.amount as amount, o.amount as totalAmount, '月付' as paymentMethod, 'System' as contact, '' as remarks, o.status as status FROM `order` o LEFT JOIN `user` cust ON o.user_id = cust.id LEFT JOIN `product` p ON o.product_id = p.id WHERE o.user_id = #{userId} AND o.is_delete = 0
AND o.status = #{status}
ORDER BY o.create_time DESC
